// A coarse level of a raw cube, sampling the centre post of each step x step cell.
export function stridedLevel(read, width, height, step) {
  const w = Math.ceil(width / step);
  const h = Math.ceil(height / step);
  const out = new Float32Array(w * h);
  for (let j = 0; j < h; j += 1) {
    const y = j * step + Math.floor(step / 2);
    for (let i = 0; i < w; i += 1) {
      const x = i * step + Math.floor(step / 2);
      out[j * w + i] = read(x, y);
    }
  }
  return { width: w, height: h, data: out };
}

head.src/strided.js:
// A coarse level of a raw cube, sampling the centre post of each step x step cell. A partial last
// cell, whose centre lies past the edge, samples the last row or column.
export function stridedLevel(read, width, height, step) {
  const w = Math.ceil(width / step);
  const h = Math.ceil(height / step);
  const out = new Float32Array(w * h);
  for (let j = 0; j < h; j += 1) {
    const y = Math.min(j * step + Math.floor(step / 2), height - 1);
    for (let i = 0; i < w; i += 1) {
      const x = Math.min(i * step + Math.floor(step / 2), width - 1);
      out[j * w + i] = read(x, y);
    }
  }
  return { width: w, height: h, data: out };
}

head.tests/strided.test.js:
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { rawReader } from '../src/raw.js';
import { stridedLevel } from '../src/strided.js';

test('a partial last cell samples the last row and column, not the zero outside', () => {
  // 5 x 5 posts, all 9: with step 4 the last cell holds one post, and its centre lies past the edge.
  const read = rawReader(new Float32Array(25).fill(9), 5, 5);
  const level = stridedLevel(read, 5, 5, 4);
  assert.equal(level.width, 2);
  assert.deepEqual([...level.data], [9, 9, 9, 9]);
});

test('whole cells still sample their centre', () => {
  const data = Float32Array.from({ length: 16 }, (_, i) => i);
  const level = stridedLevel(rawReader(data, 4, 4), 4, 4, 2);
  assert.deepEqual([...level.data], [5, 7, 13, 15]);
});
